import{_ as t,o,c as d,ag as a}from"./chunks/framework.D1z9wg1y.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),s={name:"architecture.md"};function c(l,e,n,r,i,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="the-three-layers" tabindex="-1">The three layers <a class="header-anchor" href="#the-three-layers" aria-label="Permalink to &quot;The three layers&quot;">​</a></h2><p>An installation comes from three layers. <code>harness install</code> reads all three and writes the configuration of each frontend.</p><table tabindex="0"><thead><tr><th style="text-align:left;">layer</th><th style="text-align:left;">where it is</th><th style="text-align:left;">what it holds</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>the harness</strong></td><td style="text-align:left;">this repository, public</td><td style="text-align:left;">the neutral sources of the agents, skills, rules, commands and the core instruction file; the adapters of the frontends; the guard hooks; the settings template; the git hooks, workflows and scripts</td></tr><tr><td style="text-align:left;"><strong>the profile</strong></td><td style="text-align:left;"><code>~/.config/research-harness/</code>, private</td><td style="text-align:left;"><code>profile.toml</code>, every value that names a person, an institution or a machine, and <code>models.toml</code>, the model of each tier for each frontend; <a href="./profile">profile.md</a> names each key</td></tr><tr><td style="text-align:left;"><strong>the tree instructions</strong></td><td style="text-align:left;">the directory that the profile key <code>tree_agents</code> names, private</td><td style="text-align:left;">instruction text about the user&#39;s own research tree, in the layout of <code>~/.claude/</code></td></tr></tbody></table><p>The sources of the instruction layer name no person, no repository of a research tree and no organisation. A value of that kind goes into the profile, and a template of the harness names its key. <code>harness leaks</code> checks the repository for the private strings of the profile. A rule or a fact about one research tree goes into the tree instructions. <code>adapters/claude/CLAUDE.md</code> imports their <code>instructions/research-tree.md</code>, and OpenCode and oh-my-pi read that file too. So a user adapts the harness without a change of the repository.</p><h2 id="the-state-in-claude" tabindex="-1">The state in <code>~/.claude</code> <a class="header-anchor" href="#the-state-in-claude" aria-label="Permalink to &quot;The state in `~/.claude`&quot;">​</a></h2><p><code>~/.claude/</code> holds files of four kinds. Each kind has one owner.</p><table tabindex="0"><thead><tr><th style="text-align:left;">files</th><th style="text-align:left;">owner</th><th style="text-align:left;">how they change</th></tr></thead><tbody><tr><td style="text-align:left;">the installed layer: <code>CLAUDE.md</code>, <code>RTK.md</code>, the status line script, <code>agents/</code>, <code>skills/</code>, <code>rules/</code>, <code>instructions/</code>, <code>commands/</code> and <code>hooks/</code></td><td style="text-align:left;"><code>harness install --apply</code>, from the harness and the tree instructions</td><td style="text-align:left;">edit the source, then install; the settings template denies an edit of an installed copy</td></tr><tr><td style="text-align:left;">the stamp <code>.harness-install.json</code></td><td style="text-align:left;"><code>harness install --apply</code></td><td style="text-align:left;">written after each install; the <code>SessionStart</code> hook compares it with the sources</td></tr><tr><td style="text-align:left;">the sections <code>permissions</code>, <code>hooks</code>, <code>sandbox</code> and <code>modelSettings</code> of <code>settings.json</code></td><td style="text-align:left;"><code>harness install --apply</code>, from the settings template</td><td style="text-align:left;">edit the template, then install; the install keeps the other keys of the file</td></tr><tr><td style="text-align:left;">everything else: the other keys of <code>settings.json</code>, the memory and the sessions below <code>projects/</code>, the plans</td><td style="text-align:left;">Claude Code</td><td style="text-align:left;">the harness does not write them</td></tr></tbody></table><p><code>~/.claude.json</code> belongs to Claude Code too. Only <code>harness trust --apply</code> writes it, and it changes only the trust of each repository of the research tree. The Julia environment of the scripts is outside <code>~/.claude/</code>, in <code>~/.local/share/research-harness/julia/</code>.</p><h2 id="the-claude-code-layer" tabindex="-1">The Claude Code layer <a class="header-anchor" href="#the-claude-code-layer" aria-label="Permalink to &quot;The Claude Code layer&quot;">​</a></h2><p><code>harness install</code> also writes the Claude Code layer into <code>~/.claude/</code>, from these sources in this repository: the five neutral directories <code>agents/</code>, <code>skills/</code>, <code>rules/</code>, <code>instructions/</code> and <code>commands/</code>, each at its own path below <code>~/.claude/</code>; <code>adapters/claude/</code>, at the top of <code>~/.claude/</code>; and <code>hooks/</code>, which goes to <code>~/.claude/hooks/</code>. The last source is the tree instructions, a private directory of instruction text about the user&#39;s own tree that mirrors the layout of <code>~/.claude/</code>; the profile key <code>tree_agents</code> names it. A file of <code>adapters/claude/</code> below a directory that a neutral directory or <code>hooks/</code> installs exits 2. A path that two sources hold, and an installed path that is a symlink, exit 2. The first file of the layer is <code>~/.claude/settings.json</code>, so that a new deny rule is in place before the files it protects: the verb replaces the sections <code>permissions</code>, <code>hooks</code>, <code>sandbox</code> and <code>modelSettings</code> from the settings template, rendered with the profile, keeps every other key, and keeps the old file as a backup. A <code>settings.json</code> that it cannot merge exits 2 before anything is written. The verb neither reads nor writes <code>~/.claude.json</code>. After the layer, <code>--apply</code> writes the stamp <code>~/.claude/.harness-install.json</code>: the sources and a SHA-256 over the paths, modes and source bytes that it installs. At each session start the <code>SessionStart</code> hook <code>hooks/install-drift.py</code> computes the same digest from the sources and warns when the two differ, when the stamp is missing, or when a source cannot be read. It only warns, and it exits 0. The settings template makes every installed path an <code>Edit</code> deny, so a session edits the sources.</p><p>The neutral directories hold the public instruction layer: the agents, the skills, the rules, the commands and <code>instructions/core.md</code>. <code>adapters/claude/</code> holds what is Claude Code&#39;s own: <code>CLAUDE.md</code>, <code>RTK.md</code> and the status line script. None of them names a repository or an organisation; a fact about the user&#39;s own tree goes into the tree instructions, and <code>CLAUDE.md</code> imports their <code>instructions/research-tree.md</code>. Edit a file here, not its installed copy in <code>~/.claude/</code>, which the next <code>--apply</code> overwrites. The OpenCode agents are rendered from <code>agents/</code>.</p><h2 id="the-neutral-vocabulary" tabindex="-1">The neutral vocabulary <a class="header-anchor" href="#the-neutral-vocabulary" aria-label="Permalink to &quot;The neutral vocabulary&quot;">​</a></h2><p>The <code>model:</code> and the <code>tools:</code> of an agent in <code>agents/</code> and a skill in <code>skills/</code> name no frontend. <code>model:</code> is a tier, and each <code>tools:</code> item a neutral tool; each adapter maps them to its frontend. A source with any other value exits 2, naming the file; so does a wildcard such as <code>mcp/kaimon/*</code>. Every other frontmatter key keeps its name and its value, and the body keeps Claude Code&#39;s tool names.</p><table tabindex="0"><thead><tr><th style="text-align:left;">neutral, in <code>agents/</code> and <code>skills/</code></th><th style="text-align:left;">Claude Code</th><th style="text-align:left;">OpenCode</th><th style="text-align:left;">oh-my-pi</th></tr></thead><tbody><tr><td style="text-align:left;"><code>model: large</code>, <code>medium</code>, <code>small</code></td><td style="text-align:left;">the <code>[claude]</code> table: <code>opus</code>, <code>sonnet</code>, <code>haiku</code></td><td style="text-align:left;">the <code>[opencode.models]</code> table</td><td style="text-align:left;">the <code>[omp]</code> table, as the roles <code>@opus</code>, <code>@sonnet</code>, <code>@haiku</code>; the <code>default</code> role takes the <code>medium</code> model</td></tr><tr><td style="text-align:left;"><code>read</code>, <code>edit</code>, <code>write</code>, <code>grep</code>, <code>glob</code></td><td style="text-align:left;"><code>Read</code>, <code>Edit</code>, <code>Write</code>, <code>Grep</code>, <code>Glob</code></td><td style="text-align:left;"><code>read</code>, <code>edit</code>, <code>edit</code>, <code>grep</code>, <code>glob</code></td><td style="text-align:left;"><code>read</code>, <code>edit</code>, <code>write</code>, <code>grep</code>, <code>glob</code></td></tr><tr><td style="text-align:left;"><code>shell</code></td><td style="text-align:left;"><code>Bash</code></td><td style="text-align:left;"><code>bash</code></td><td style="text-align:left;"><code>bash</code></td></tr><tr><td style="text-align:left;"><code>agent</code></td><td style="text-align:left;"><code>Agent</code></td><td style="text-align:left;"><code>task</code></td><td style="text-align:left;"><code>task</code></td></tr><tr><td style="text-align:left;"><code>web_search</code>, <code>web_fetch</code></td><td style="text-align:left;"><code>WebSearch</code>, <code>WebFetch</code></td><td style="text-align:left;"><code>websearch</code>, <code>webfetch</code></td><td style="text-align:left;"><code>web_search</code>, <code>read</code></td></tr><tr><td style="text-align:left;"><code>mcp/kaimon/&lt;tool&gt;</code></td><td style="text-align:left;"><code>mcp__kaimon__&lt;tool&gt;</code></td><td style="text-align:left;"><code>kaimon_&lt;tool&gt;</code></td><td style="text-align:left;"><code>mcp__kaimon_&lt;tool&gt;</code></td></tr></tbody></table><p>The Claude Code layer copies an agent or a skill with these two values rewritten in place and every other byte as it is. A table of <code>models.toml</code> that names a tier by its old name, <code>opus</code>, <code>sonnet</code> or <code>haiku</code>, exits 2 and names the rename; so does a <code>models.toml</code> without <code>[claude]</code>, and a <code>[claude]</code> model that is not a letter followed by letters, digits and <code>. _ - [ ]</code>, or that YAML reads as a boolean or null.</p><h2 id="the-opencode-and-oh-my-pi-adapters" tabindex="-1">The OpenCode and oh-my-pi adapters <a class="header-anchor" href="#the-opencode-and-oh-my-pi-adapters" aria-label="Permalink to &quot;The OpenCode and oh-my-pi adapters&quot;">​</a></h2><p>OpenCode reads <code>adapters/opencode/OPENCODE-DELTA.md</code>, which <code>harness install</code> writes as <code>AGENTS.md</code> in OpenCode&#39;s configuration directory, in place of <code>~/.claude/CLAUDE.md</code>. <code>RTK.md</code>, <code>instructions/core.md</code> and <code>instructions/research-tree.md</code> reach it through <code>instructions</code> in <code>opencode.jsonc</code>. <code>CLAUDE.md</code> holds the Claude Code mechanics only.</p><p>oh-my-pi gets its permission layer from the same settings template. <code>harness install</code> writes the overlay <code>harness.yml</code> into its agent directory, <code>$PI_CODING_AGENT_DIR</code>, else <code>~/.omp/agent</code>: <code>tools.approvalMode: yolo</code>, the <code>eval</code> tool denied, and the template&#39;s Bash entries as <code>bash.patterns</code>, every <code>deny</code>, then every <code>ask</code> as <code>prompt</code>, then every <code>allow</code>, since oh-my-pi takes the first rule that matches. oh-my-pi&#39;s own <code>config.yml</code>, which its setup and its settings panel write, is never written: oh-my-pi reads <code>harness.yml</code> over it when <code>PI_CONFIG_FILES</code> in the agent directory&#39;s <code>.env</code> names it, and the install warns until it does. Beside it go <code>extensions/guards.ts</code>, from <code>adapters/omp/guards.ts</code>, and the rendered path list <code>extensions/guard-paths.json</code>. The extension runs four of the guard hooks, from oh-my-pi&#39;s own copy in <code>hooks/</code>, on every <code>bash</code> call, <code>rm-scope.py</code> among them, the template&#39;s read denies on <code>read</code>, <code>grep</code> and <code>bash</code>, and its Edit denies on <code>edit</code> and <code>write</code>, with <code>~/.omp/**</code> added to both, except that its copies of the skills, the rules and the instructions stay readable; it refuses the paths of the template&#39;s Edit asks on <code>edit</code> and <code>write</code> too, and tells the model to ask the user in chat; it blocks the call when a guard cannot run, fails or times out.</p><p>oh-my-pi reads the same instructions. <code>harness install</code> writes <code>adapters/omp/OMP-DELTA.md</code> as <code>AGENTS.md</code> in its agent directory; its first lines import oh-my-pi&#39;s own copies of <code>RTK.md</code>, <code>instructions/core.md</code> and <code>instructions/research-tree.md</code>, and the rest states the facts of oh-my-pi. Each rule that the Claude Code layer installs goes to <code>rules/&lt;name&gt;.md</code> there, its frontmatter written anew as <code>globs: &lt;JSON list&gt;</code> and <code>description: &lt;JSON string&gt;</code>, which YAML reads as the source&#39;s <code>paths</code> and <code>description</code>: oh-my-pi lists it by its name, globs and <code>description</code>. A rule source exits 2 unless its frontmatter holds only one line <code>description: &lt;text&gt;</code>, not blank, and at most one line <code>paths: [&quot;…&quot;, …]</code>, with no tab and no whitespace at a line&#39;s edge (<code>render_rule</code> gives the grammar), and a rule source in a subdirectory of <code>rules/</code> exits 2, as oh-my-pi reads none. The skills are oh-my-pi&#39;s own copies in <code>skills/</code>, which it reads through <code>skill://</code>.</p><p>oh-my-pi gets the agents, the models and the MCP entry too. Each agent of <code>agents/</code> goes to <code>agents/&lt;name&gt;.md</code> in its agent directory, with <code>name</code>, <code>description</code>, <code>tools</code> mapped by the table <code>TOOLS</code> of <code>adapters/omp/adapter.py</code> (a tool it does not map exits 2), <code>model</code> the model of its tier or its override, <code>thinking-level</code> its effort from the model tables, <code>skills</code> as <code>autoloadSkills</code>, and the body, after an &quot;Under oh-my-pi&quot; section from <code>adapters/omp/UNDER-OMP.md</code> for an agent that uses a Claude Code mechanism; each council seat gets a copy. The model tables of <code>models.toml</code>, which OpenCode shares, give the model of each tier, <code>large</code>, <code>medium</code> and <code>small</code>; <code>harness.yml</code> holds <code>modelRoles.default</code>, the <code>medium</code> model. <code>mcp.json</code> holds Kaimon alone, over HTTP, with its token read from <code>~/.config/kaimon/opencode-token</code> by a command when oh-my-pi connects, so that no secret is in the file.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The sources of the instruction layer are neutral: they belong to no one frontend. What is one frontend&#39;s own goes below <code>adapters/&lt;frontend&gt;/</code>. The other top-level directories belong to no frontend either: <code>hooks/</code> holds the guard scripts that Claude Code and oh-my-pi both call, <code>settings/</code> the policy source of all three frontends, and the rest the tools.</p><table tabindex="0"><thead><tr><th style="text-align:left;">directory</th><th style="text-align:left;">holds</th></tr></thead><tbody><tr><td style="text-align:left;"><code>agents/</code>, <code>skills/</code>, <code>rules/</code>, <code>instructions/</code>, <code>commands/</code></td><td style="text-align:left;">the neutral sources: the agents, skills, rules, the core instruction file and the commands, which <code>harness install</code> copies into <code>~/.claude/</code> at the same path, and from which it renders the OpenCode and oh-my-pi agents and the oh-my-pi rules</td></tr><tr><td style="text-align:left;"><code>adapters/claude/</code></td><td style="text-align:left;">Claude Code&#39;s own: <code>CLAUDE.md</code>, <code>RTK.md</code> and the status line script, which <code>harness install</code> copies to the top of <code>~/.claude/</code></td></tr><tr><td style="text-align:left;"><code>adapters/opencode/</code></td><td style="text-align:left;">the OpenCode configuration, plugins, global instruction file, and the agents that have no Claude Code source</td></tr><tr><td style="text-align:left;"><code>adapters/omp/</code></td><td style="text-align:left;">the oh-my-pi guard extension, global instruction file and agent text</td></tr><tr><td style="text-align:left;"><code>bin/</code>, <code>lib/harness/</code></td><td style="text-align:left;">the <code>harness</code> command</td></tr><tr><td style="text-align:left;"><code>adapters/&lt;frontend&gt;/adapter.py</code></td><td style="text-align:left;">each frontend&#39;s part of the <code>harness</code> command, which <code>lib/harness/frontends.py</code> loads: the Claude Code layer, the settings and the trust; the generators of the OpenCode agents, permission block and skill links; the generator of oh-my-pi&#39;s <code>config.yml</code>, rules, agents and <code>mcp.json</code></td></tr><tr><td style="text-align:left;"><code>hooks/</code></td><td style="text-align:left;">the shared guard scripts: Claude Code <code>PreToolUse</code> hooks that refuse unsafe shell commands, which oh-my-pi&#39;s <code>guards.ts</code> calls too, the <code>SessionStart</code> hook that warns when <code>~/.claude/</code> is behind its sources, and their test cases (<code>probe.py</code>)</td></tr><tr><td style="text-align:left;"><code>settings/</code></td><td style="text-align:left;">the permission and sandbox settings template, the policy source of all three frontends</td></tr><tr><td style="text-align:left;"><code>githooks/</code></td><td style="text-align:left;">git hooks and GitHub Actions workflow templates for Julia packages, and their installers</td></tr><tr><td style="text-align:left;"><code>scripts/</code></td><td style="text-align:left;">Julia test, mutation, and code-structure tools; transcript and lint tools</td></tr><tr><td style="text-align:left;"><code>launchagents/</code></td><td style="text-align:left;">macOS launchd job templates</td></tr><tr><td style="text-align:left;"><code>ast-grep/</code>, <code>fatou.toml</code></td><td style="text-align:left;">linter configuration</td></tr><tr><td style="text-align:left;"><code>agent-workflows/</code></td><td style="text-align:left;">workflow scripts for fan-out over many repositories</td></tr><tr><td style="text-align:left;"><code>examples/</code></td><td style="text-align:left;">the example profile and model tables</td></tr><tr><td style="text-align:left;"><code>docs/</code></td><td style="text-align:left;">the pages of the documentation site in <code>docs/src/</code>, and its VitePress build</td></tr></tbody></table>',24)])])}const u=t(s,[["render",c]]);export{m as __pageData,u as default};
